<article class="directory-expert-card {{ empty($item['photo'])?'without-image':'' }}"><a class="directory-expert-main" href="{{ P::path('experts',$item) }}"><div class="directory-expert-heading">@if($cover=P::media($item['photo']??null))<img src="{{ $cover }}" alt="{{ P::title($item) }}" width="78" height="94" loading="lazy">@endif<div><span class="directory-status {{ ($item['status']??'')==='suspended'?'suspended':'' }}">{{ P::t(($item['status']??'')==='suspended'?'تعلیق‌شده':'کارشناس فعال') }}</span><h2>{{ P::title($item) }}</h2><p>{{ P::t('شماره پروانه') }}: <b>{{ $item['license_number']??'' }}</b></p></div></div><dl class="directory-expert-facts">@foreach(['گروه'=>P::title($item['expert_group']??[]),'رشته'=>P::title($item['discipline']??[]),'شهر'=>$item['city']??''] as $text=>$value)<div><dt>{{ P::t($text) }}</dt><dd>{{ $value }}</dd></div>@endforeach</dl><div class="directory-qualification-tags">@foreach(array_slice($item['qualifications']??[],0,3) as $q)<span>{{ P::title($q) }}</span>@endforeach</div><span class="read-more">{{ P::t('مشاهده پروفایل') }} ↗</span></a><div class="directory-contact-links">@if(!empty($item['phone']))<a href="tel:{{ preg_replace('/[^+0-9]/','',$item['phone']) }}">{{ $item['phone'] }}</a>@endif @if(!empty($item['email']))<a href="mailto:{{ $item['email'] }}">{{ P::t('ایمیل') }}</a>@endif</div></article>